let state={char:-1,user:-1,users:[],characters:[],messages:{},offline:false};try{Object.assign(state,JSON.parse(localStorage.getItem('iris-v1')||'{}'))}catch{};
state.users=(Array.isArray(state.users)?state.users:[]).map(u=>typeof u==='string'?{name:u,nickname:'',birthday:'',details:'',avatar:''}:{name:'',nickname:'',birthday:'',details:'',avatar:'',...u}).filter(u=>!['我','另一个我'].includes(u.name));
