  if(action.type==='transfer_reply'){const pending=[...conversationItems].reverse().find(item=>item.mine&&item.type==='transfer'&&(item.status==='pending'||item.status==='sent'));if(pending&&(action.action==='accept'||action.action==='return'))pending.status=action.action==='accept'?'accepted':'returned';continue}
  const createdAt=Date.now();
  if(action.type==='transfer'){const amount=Number(action.amount);if(Number.isFinite(amount)&&amount>0)structured.push({mine:false,type:'transfer',amount:Math.min(999999,amount),note:String(action.note||'给你').slice(0,100),status:'pending',createdAt})}
