 const entries=values.map((item,index)=>{
  if(typeof item==='string')return{name:`条目 ${index+1}`,content:item};
  if(!item||typeof item!=='object')return null;
  const content=item.content??item.prompt??item.text??item.description??item.system_prompt??item.value??'';
  return String(content).trim()?{name:item.name||item.title||item.comment||item.identifier||item.role||`条目 ${index+1}`,section:String(item.section||item.category||item.group||''),choiceGroup:String(item.choiceGroup||item.choice_group||''),content:String(content),enabled:item.enabled!==false,sourceOrder:index}:null;
 }).filter(Boolean);
 if(entries.length)return entries;
