  content.innerHTML=globalTabs+pageHead+`<div class="api-config-panel"><div class="api-config-heading"><h2>配置</h2><button type="button" id="addApiConfig" class="api-add-config">＋ 添加新配置</button></div>${savedConfigs?`<div class="api-config-list">${savedConfigs}</div>`:''}<form id="apiForm" class="settings-form settings-page-form"><label>配置名称<input id="apiName" autocomplete="off" placeholder="例如：OpenAI" value="${esc(current?.name||'')}"></label><label>API 地址<input id="apiUrl" type="url" autocomplete="url" placeholder="https://api.example.com/v1" value="${esc(current?.url??(editingApiConfigId?cfg.apiUrl:''))}"></label><label>API Key<input id="apiKey" type="password" autocomplete="off" placeholder="输入 API Key" value="${esc(current?.key??(editingApiConfigId?cfg.apiKey:''))}"></label><label>模型名称<input id="apiModel" list="apiModelOptions" autocomplete="off" placeholder="拉取或输入模型名称" value="${esc(current?.model??(editingApiConfigId?cfg.apiModel:''))}"><datalist id="apiModelOptions"></datalist></label><div class="api-form-actions"><button type="button" id="fetchModels" class="settings-secondary"  >拉取模型</button><button type="submit" class="settings-primary">保存配置</button></div><p class="settings-note" id="apiFeedback">模型列表将从填写的 API 地址拉取。</p></form></div>`;
